// Handler : on_acq_add_clicked
// Widget  : #acq_add_btn
// Signal  : clicked
function on_acq_add_clicked(payload) {
  const nameEl  = Composer.widget('acq_name_entry');
  const typeEl  = Composer.widget('acq_type_combo');
  const valueEl = Composer.widget('acq_value_entry');
  const list    = Composer.widget('acq_list');
  if (!nameEl || !typeEl || !valueEl || !list) {
    console.warn('[add] widgets introuvables');
    return;
  }

  const name  = nameEl.value.trim();
  const type  = typeEl.value;
  const value = valueEl.value.trim();
  if (!name || !value) return;

  let v = value;
  if (type === 'Nombre entier')  v = parseInt(value, 10);
  if (type === 'Nombre décimal') v = parseFloat(value);
  if (typeof v === 'number' && isNaN(v)) v = value;

  const row = document.createElement('div');
  row.style.cssText =
    'display:flex;gap:8px;padding:4px 8px;' +
    'background:#f8f8f8;border-radius:4px;font-size:12px;align-items:center';
  row.innerHTML =
    '<b style="flex:1">' + name + '</b>' +
    '<span style="color:#888">' + type + '</span>' +
    '<span style="color:#3584e4;font-weight:600">' + v + '</span>';

  row.dataset.name  = name;
  row.dataset.type  = type;
  row.dataset.value = v;

  list.appendChild(row);

  valueEl.value = '';
  valueEl.focus();

  const status = Composer.widget('acq_status');
  if (status) status.textContent = list.children.length + ' données';

  Composer.setStatus('+ ' + name + ' = ' + v);
}

