on_acq_send_clicked.code:
// Handler : on_acq_send_clicked
// Widget  : #acq_send_btn
// Signal  : clicked
function on_acq_send_clicked(payload) {
  const list    = Composer.widget('acq_list');
  const trtList = Composer.widgetIn('traitement.glade', 'trt_data_list');
  if (!list) return;
  if (!trtList) {
    Composer.setStatus('⚠ traitement.glade non chargé');
    return;
  }

  trtList.innerHTML = '';

  const rows = Array.prototype.slice.call(list.children);
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    const copy = document.createElement('div');
    copy.style.cssText =
      'padding:3px 6px;font-size:12px;' +
      'background:#eef4fc;border-radius:3px;margin-bottom:3px';
    copy.textContent = r.dataset.name + ' = ' + r.dataset.value;
    copy.dataset.value = r.dataset.value;
    copy.dataset.name  = r.dataset.name;
    trtList.appendChild(copy);
  }

  const status = Composer.widgetIn('traitement.glade', 'trt_status');
  if (status) status.textContent = rows.length + ' donnée(s)';

  Composer.setStatus('📤 ' + rows.length + ' données envoyées');
}

