// Handler : on_op_changed
// Widget  : #op_sum
// Signal  : toggled
function on_op_changed(payload) {
  const ids = ['op_sum', 'op_avg', 'op_min', 'op_max', 'op_count'];
  let current = '?';
  for (let i = 0; i < ids.length; i++) {
    const wrap = Composer.widget(ids[i]);
    if (!wrap) continue;
    const input = wrap.querySelector('input[type="radio"]');
    if (input && input.checked) { current = ids[i]; break; }
  }
  Composer.setStatus('Opération : ' + current);
}

on_exec_clicked.code:
// Handler : on_exec_clicked
// Widget  : #trt_exec_btn
// Signal  : clicked
function on_exec_clicked(payload) {
  const trtList     = Composer.widget('trt_data_list');
  const resultLabel = Composer.widget('trt_result_label');
  const detailLabel = Composer.widget('trt_result_detail');
  const historyBox  = Composer.widget('trt_history');

  if (!trtList || !resultLabel) {
    console.warn('[exec] widgets introuvables');
    return;
  }

  const rows = Array.prototype.slice.call(trtList.children);
  const values = [];
  for (let i = 0; i < rows.length; i++) {
    const v = parseFloat(rows[i].dataset.value);
    if (!isNaN(v)) values.push(v);
  }

  if (!values.length) {
    resultLabel.textContent = '—';
    if (detailLabel) detailLabel.textContent = 'Aucune donnée numérique.';
    return;
  }

  let op = 'sum';
  const opIds = ['op_sum', 'op_avg', 'op_min', 'op_max', 'op_count'];
  for (let i = 0; i < opIds.length; i++) {
    const wrap = Composer.widget(opIds[i]);
    if (!wrap) continue;
    const input = wrap.querySelector('input[type="radio"]');
    if (input && input.checked) {
      op = opIds[i].replace('op_', '');
      break;
    }
  }

  let result, label;
  if (op === 'sum') {
    result = values.reduce(function (a, b) { return a + b; }, 0);
    label = 'Σ';
  } else if (op === 'avg') {
    result = values.reduce(function (a, b) { return a + b; }, 0) / values.length;
    label = 'x̄';
  } else if (op === 'min') {
    result = Math.min.apply(null, values);
    label = 'min';
  } else if (op === 'max') {
    result = Math.max.apply(null, values);
    label = 'max';
  } else if (op === 'count') {
    result = values.length;
    label = 'count';
  }

  resultLabel.textContent = label + ' = ' + result;
  if (detailLabel) {
    detailLabel.textContent =
      'Sur ' + values.length + ' valeur(s) : ' + values.join(', ');
  }

  if (historyBox) {
    const entry = document.createElement('div');
    entry.style.cssText = 'padding:2px 6px;font-size:11px;color:#666';
    entry.textContent =
      '[' + new Date().toLocaleTimeString() + '] ' +
      label + ' = ' + result;
    historyBox.appendChild(entry);
    historyBox.scrollTop = historyBox.scrollHeight;
  }

  Composer.setStatus('▶ ' + label + ' = ' + result);
}

